// Определяем количество сегментов
const int segmentsX = 14; // Количество сегментов по X
const int segmentsY = 14; // Количество сегментов по Y
const int totalSegments = segmentsX * segmentsY;

// Функция для получения случайного индекса
int randomIndex(int seed, int max) {
    return (seed * 48271) % max; // Простой псевдослучайный генератор
}

void mainImage(out vec4 FragColor, in vec2 fragCoord) {
    // Получаем разрешение текстуры
    vec2 resolution = iResolution.xy;

    // Получаем нормализованные координаты фрагмента
    vec2 uv = fragCoord / resolution;

    // Размер каждого сегмента
    vec2 segmentSize = vec2(1.0 / float(segmentsX), 1.0 / float(segmentsY));

    // Определяем текущий сегмент
    int segmentX = int(uv.x / segmentSize.x);
    int segmentY = int(uv.y / segmentSize.y);
    int currentSegmentIndex = segmentX + segmentY * segmentsX;

    // Генерируем массив уникальных индексов сегментов
    int indices[totalSegments];
    for (int i = 0; i < totalSegments; i++) {
        indices[i] = i; // Инициализируем массив индексов
    }

    // Перемешиваем индексы
    int timeIndex = int(iTime * 10.0); // Увеличиваем скорость перемешивания
    for (int i = totalSegments - 1; i > 0; i--) {
        int j = randomIndex(timeIndex + i, totalSegments);
        // Меняем местами элементы
        int temp = indices[i];
        indices[i] = indices[j];
        indices[j] = temp;
    }

    // Получаем уникальный сегмент для текущего фрагмента
    int uniqueSegmentIndex = indices[currentSegmentIndex];

    // Вычисляем координаты уникального сегмента
    int uniqueSegmentX = uniqueSegmentIndex % segmentsX;
    int uniqueSegmentY = uniqueSegmentIndex / segmentsX;

    // Вычисляем UV координаты для уникального сегмента
    vec2 uniqueSegmentUV = vec2(float(uniqueSegmentX) * segmentSize.x, float(uniqueSegmentY) * segmentSize.y);

    // Получаем цвет из входного изображения через ichannel0
    vec4 color = texture(iChannel0, uniqueSegmentUV + (uv - vec2(float(segmentX) * segmentSize.x, float(segmentY) * segmentSize.y)));

    // Устанавливаем цвет фрагмента
    FragColor = color; // Используем выходной параметр FragColor
}
